update public.content_items c set image_url = m.url, image_credit = m.credit, updated_at = now()
from m
where c.item_type = 'word' and c.image_url is null and (
  (c.learning_language = 'en' and m.en <> '' and c.source_text = m.en) or
  (c.learning_language = 'th' and m.th <> '' and c.source_text = m.th) or
  (c.learning_language = 'he' and m.he <> '' and c.source_text = m.he)
);
select learning_language, translation_language, count(*) filter (where image_url is not null) as with_image, count(*) as words from public.content_items where item_type = 'word' group by 1,2 order by 1,2;